+        LocalTensor<int32_t> rm = rowMapBuf_.Get<int32_t>();
+        K2qCsrCommon::CopyInInt32(rm, rowMapGm_, tiling_->rowMapElems);
+    }
+    for (int64_t hid = 0; hid < H_; ++hid) {
+        HistOneGroupHead(bid, hid);
+    }
