+                    }
+                }
+            }
+            if (useQPingPong_ != 0 && qsNext < q1) {
+                PipeBarrier<PIPE_ALL>();
+                LocalTensor<int32_t> tmp = cur;
+                cur = nxt;
+                nxt = tmp;
+            }
+            qs = qsNext;
+        }
+    }
+    if (batchN > 0) {
+        K2qCsrCommon::FlushStoreBatch(qIndGm_, slotGm_, base, posB, qB, sB, batchN);
+    }
+}
