+    const K2qCsrTilingData *tiling_;
+    TPipe *pipe_;
+
+    GlobalTensor<int32_t> cuQGm_;
+    GlobalTensor<int32_t> cuBGm_;
+    GlobalTensor<int32_t> rowMapGm_;
+    GlobalTensor<int32_t> tokenBatchGm_;
+    GlobalTensor<int32_t> rowCountsGm_;
